const HUMAN_LABELS={"interviewee.answer":"Interviewee Answer","gate.auto_decision":"Gate Auto Decision","gate.simulated_expert_opinion":"Gate Simulated Expert Opinion","not_started":"Not Started","in_progress":"In Progress","intent":"Start","intent_model":"Start"};
function humanLabel(value){if(value==null)return '';let key=String(value);if(HUMAN_LABELS[key])return HUMAN_LABELS[key];return key.replace(/[._-]+/g,' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/\b\w/g,c=>c.toUpperCase())}
function markdownInline(text){return esc(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')}
function markdownHtml(text){let lines=String(text||'').split('\n'),html=[],inList=false;for(let line of lines){if(/^#{1,4} /.test(line)){if(inList){html.push('</ul>');inList=false}let level=line.match(/^#+/)[0].length;html.push(`<h${level}>${markdownInline(line.slice(level+1))}</h${level}>`)}else if(/^[-*] /.test(line)){if(!inList){html.push('<ul>');inList=true}html.push(`<li>${markdownInline(line.slice(2))}</li>`)}else if(!line.trim()){if(inList){html.push('</ul>');inList=false}}else{if(inList){html.push('</ul>');inList=false}html.push(`<p>${markdownInline(line)}</p>`)}}if(inList)html.push('</ul>');return html.join('')}
function pretty(v){return `<pre class="json-view">${esc(JSON.stringify(v,null,2))}</pre>`}
function cards(rows,id,title,render){return `<section class="bundle-section" id="${id}"><div class="panel-title"><h3>${title}</h3><span class="eyebrow">${rows.length} records</span></div><div class="bundle-cards">${rows.map(render).join('')||'<div class="notice">No records in this artifact.</div>'}</div></section>`}
function graphView(g){
 const order={need:0,requirement:1,spec:2,criterion:2,test:3},colors={need:'#bbf246',requirement:'#40c99b',spec:'#6aa8ff',criterion:'#b387ff',test:'#ff7b59'};
 const groups=[0,1,2,3].map(x=>g.nodes.filter(n=>(order[n.kind]??2)===x));let pos={},W=1040,H=Math.max(390,...groups.map(x=>x.length*74+70));groups.forEach((rows,x)=>rows.forEach((n,i)=>pos[n.id]={x:90+x*285,y:55+i*74}));
 const edges=g.edges.filter(e=>pos[e.from]&&pos[e.to]).map(e=>`<path class="trace-edge" d="M${pos[e.from].x+72},${pos[e.from].y} C${pos[e.from].x+140},${pos[e.from].y} ${pos[e.to].x-140},${pos[e.to].y} ${pos[e.to].x-72},${pos[e.to].y}"><title>${esc(e.kind)}</title></path>`).join('');
 const nodes=g.nodes.filter(n=>pos[n.id]).map(n=>`<g class="trace-node" tabindex="0" role="button" aria-label="${esc(n.id)} ${esc(humanLabel(n.kind))}" data-node="${esc(n.id)}" transform="translate(${pos[n.id].x},${pos[n.id].y})"><rect x="-72" y="-23" width="144" height="46" rx="16" style="--node:${colors[n.kind]||'#aaa'}"/><text y="-3" text-anchor="middle">${esc(n.id)}</text><text y="13" text-anchor="middle" class="node-kind">${esc(humanLabel(n.kind))}</text></g>`).join('');
 return `<div class="trace-shell"><div class="trace-canvas"><svg class="trace-map" viewBox="0 0 ${W} ${H}">${edges}${nodes}</svg><div id="trace-tooltip" class="trace-tooltip hidden" role="tooltip"></div></div><aside id="node-detail"><div class="eyebrow">Select a node</div><h3>Trace evidence</h3><p>Click any need, requirement, spec, criterion or test to inspect its content and connected edges.</p></aside></div>`;
}
